function MediConnectApp() {
  const [view, setView] = useState<View>("overview");
  const [session, setSession] = useState<SessionUser | null>(null);
  const [authOpen, setAuthOpen] = useState(false);
  const [authMode, setAuthMode] = useState<"signin" | "signup">("signin");
  const [dark, setDark] = useState(false);
  const [mobileNav, setMobileNav] = useState(false);
  const [search, setSearch] = useState("");
  const [activeDoctor, setActiveDoctor] = useState<typeof doctors[number] | null>(null);
  const [appointmentOpen, setAppointmentOpen] = useState(false);
  const [role, setRole] = useState<UserRole>("patient");
  const navigate = useNavigate();

  useEffect(() => {
    document.documentElement.classList.toggle("dark", dark);
    const restore = async () => { const { data } = await supabase.auth.getSession(); if (data.session?.user) setSession({ id: data.session.user.id, email: data.session.user.email, role: "patient", name: data.session.user.user_metadata?.full_name ?? "Amara" }); };
    void restore();
    const { data: listener } = supabase.auth.onAuthStateChange((_event, current) => { if (current?.user) setSession({ id: current.user.id, email: current.user.email, role: "patient", name: current.user.user_metadata?.full_name ?? "Amara" }); else setSession(null); });
    return () => listener.subscription.unsubscribe();
  }, [dark]);

  const openAuth = (mode: "signin" | "signup" = "signin") => { setAuthMode(mode); setAuthOpen(true); };
  const signOut = async () => { await supabase.auth.signOut(); setSession(null); toast.success("Signed out safely"); };
  const selectView = (next: View) => { setView(next); setMobileNav(false); };
  const isLanding = !session && view === "overview";

  if (isLanding) return <Landing onAuth={openAuth} onNavigate={selectView} onDark={() => setDark(!dark)} dark={dark} />;
  return <AppShell session={session ?? { id: "demo", name: "Amara Okafor", email: "amara@example.com", role }} view={view} selectView={selectView} dark={dark} setDark={setDark} search={search} setSearch={setSearch} mobileNav={mobileNav} setMobileNav={setMobileNav} onSignOut={signOut} onAuth={openAuth} onDoctor={(doctor) => { setActiveDoctor(doctor); setAppointmentOpen(true); }} onDemoRole={(next) => { setRole(next); toast.success(`Viewing ${next.replaceAll("_", " ")} workspace`); }} />;
}

function Logo({ dark = false }: { dark?: boolean }) { return <div className="flex items-center gap-3"><div className="grid size-11 place-items-center rounded-2xl bg-gradient-to-br from-brand to-cyan-400 font-display text-xl font-bold text-primary-foreground shadow-lg shadow-brand/25">M</div><div><p className={dark ? "font-display text-lg font-bold leading-none text-foreground" : "font-display text-lg font-bold leading-none text-foreground"}>MediConnect <span className="text-primary">AI</span></p><p className="mt-1 text-[11px] tracking-wide text-muted-foreground">Healthcare · Connected · Intelligent</p></div></div>; }

function Landing({ onAuth, onNavigate, dark, onDark }: { onAuth: (mode?: "signin" | "signup") => void; onNavigate: (view: View) => void; dark: boolean; onDark: () => void }) {
  return <div className="page-glow min-h-screen overflow-hidden"><div className="mx-auto max-w-[1440px] px-5 py-7 lg:px-10">
    <header className="flex items-center justify-between"><Logo /><div className="hidden items-center gap-2 rounded-2xl bg-foreground/[0.04] p-1.5 md:flex">{["Platform", "Doctors", "Hospitals", "Labs", "Medicines"].map((item, i) => <button key={item} onClick={() => onNavigate(i === 1 ? "doctors" : i === 2 ? "hospitals" : i === 3 ? "labs" : i === 4 ? "medicine" : "overview")} className={i === 0 ? "rounded-xl bg-primary/15 px-4 py-2 text-sm font-medium text-primary" : "rounded-xl px-4 py-2 text-sm text-muted-foreground transition hover:bg-foreground/5 hover:text-foreground"}>{item}</button>)}</div><div className="flex items-center gap-2"><button aria-label="Toggle dark mode" onClick={onDark} className="grid size-10 place-items-center rounded-xl text-muted-foreground transition hover:bg-foreground/5">{dark ? <Sun className="size-4" /> : <Moon className="size-4" />}</button><Button variant="ghost" className="hidden sm:inline-flex" onClick={() => onAuth("signin")}>Sign in</Button><Button onClick={() => onAuth("signup")}>Get started</Button></div></header>
    <section className="grid items-center gap-10 pb-14 pt-14 lg:grid-cols-12 lg:pt-20"><div className="lg:col-span-7"><Badge className="border border-primary/20 bg-primary/10 px-3 py-1.5 text-primary"><span className="pulse-dot mr-2 inline-block size-1.5 rounded-full bg-primary" />AI health assistant online</Badge><h1 className="mt-6 max-w-3xl font-display text-5xl font-bold leading-[1.04] tracking-tight text-foreground sm:text-6xl lg:text-7xl">Your complete healthcare, <span className="text-primary">connected</span> in one place.</h1><p className="mt-6 max-w-xl text-lg leading-relaxed text-muted-foreground">Connect with doctors, hospitals, diagnostic labs and pharmacies through one intelligent platform — with AI guidance, live availability and secure records.</p><div className="mt-8 flex flex-wrap gap-3"><Button size="lg" onClick={() => onNavigate("doctors")}>Find a doctor <ArrowRight /></Button><Button variant="outline" size="lg" onClick={() => onNavigate("assistant")}>Talk to AI assistant <MessageCircle /></Button><Button variant="ghost" size="lg" onClick={() => onNavigate("hospitals")}>Find a hospital</Button></div><div className="mt-9 flex flex-wrap gap-8">{[["1,240","Hospitals connected"],["18,500","Doctors available"],["3,400","Diagnostic labs"],["1.2M","Patients served"]].map(([value,label]) => <div key={label}><p className="font-display text-3xl font-bold text-foreground">{value}</p><p className="mt-1 text-xs text-muted-foreground">{label}</p></div>)}</div></div><div className="lg:col-span-5"><AssistantPreview onNavigate={onNavigate} /></div></section>
    <div className="grid gap-5 lg:grid-cols-12"><HospitalAvailability className="lg:col-span-5" /><BedChart className="lg:col-span-4" /><Upcoming className="lg:col-span-3" /></div>
    <section className="mt-5 grid grid-cols-2 gap-4 md:grid-cols-4">{[["Book a doctor","18,500 specialists","doctors",Stethoscope],["Visit a lab","Track reports","labs",TestTube2],["Find medicine","Compare prices","medicine",Pill],["Emergency help","Find nearest ER","hospitals",AlertTriangle]].map(([title,sub,target,Icon]) => <button key={title as string} onClick={() => target === "hospitals" ? onNavigate("hospitals") : onNavigate(target as View)} className={target === "hospitals" ? "rounded-2xl bg-gradient-to-br from-danger to-rose-500 p-4 text-left text-destructive-foreground shadow-lg shadow-danger/20" : "glass-panel rounded-2xl p-4 text-left transition hover:-translate-y-1"}><Icon className="mb-4 size-5" /><p className="text-sm font-semibold">{title as string}</p><p className="mt-1 text-xs opacity-70">{sub as string}</p></button>)}</section>
    <p className="mx-auto mt-10 max-w-3xl text-center text-xs text-muted-foreground">This AI assistant provides general health information and does not replace professional medical advice, diagnosis, or treatment.</p>
  </div><AuthDialog open={false} onOpenChange={() => undefined} mode="signin" setMode={() => undefined} /></div>;
}

function AssistantPreview({ onNavigate }: { onNavigate: (view: View) => void }) { return <div className="glass-deep rounded-3xl p-5 text-primary-foreground"><div className="flex items-center justify-between"><div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-xl bg-gradient-to-br from-brand to-cyan-400 font-display font-bold text-primary-foreground">✦</div><div><p className="text-sm font-semibold">AI Health Assistant</p><p className="text-[10px] text-brand">Listening · not a diagnosis</p></div></div><Badge className="border-0 bg-foreground/10 text-[10px] text-muted-foreground">Secure</Badge></div><div className="mt-5 space-y-3 text-sm"><div className="flex gap-2"><div className="grid size-7 shrink-0 place-items-center rounded-full bg-foreground/10 text-[10px]">✦</div><p className="max-w-[85%] rounded-2xl rounded-tl-md bg-foreground/10 px-3.5 py-2.5 text-foreground/80">I’m here to help. You mentioned a fever — how long has it lasted?</p></div><div className="flex justify-end"><p className="max-w-[78%] rounded-2xl rounded-tr-md bg-primary px-3.5 py-2.5 text-primary-foreground">About 2 days, with a mild headache.</p></div><div className="flex gap-2"><div className="grid size-7 shrink-0 place-items-center rounded-full bg-foreground/10 text-[10px]">✦</div><p className="max-w-[88%] rounded-2xl rounded-tl-md bg-foreground/10 px-3.5 py-2.5 text-foreground/80">Rest and fluids may help. If it persists past 3 days or chest pain appears, please see a doctor.</p></div></div><div className="mt-5 flex gap-2"><div className="flex-1 rounded-xl border border-foreground/10 bg-foreground/5 px-3.5 py-3 text-xs text-muted-foreground">Describe your symptoms…</div><Button size="icon" onClick={() => onNavigate("assistant")}><Send /></Button></div><div className="mt-3 flex flex-wrap gap-2"><Button size="sm" variant="outline" className="border-foreground/15 bg-foreground/5 text-foreground hover:bg-foreground/10" onClick={() => onNavigate("doctors")}>Book a doctor</Button><Button size="sm" variant="outline" className="border-foreground/15 bg-foreground/5 text-foreground hover:bg-foreground/10" onClick={() => onNavigate("hospitals")}>Nearest hospital</Button><Button size="sm" variant="destructive" onClick={() => toast.error("For emergencies, contact local emergency services now.")}>Emergency</Button></div></div>; }

function AppShell({ session, view, selectView, dark, setDark, search, setSearch, mobileNav, setMobileNav, onSignOut, onAuth, onDoctor, onDemoRole }: { session: SessionUser; view: View; selectView: (view: View) => void; dark: boolean; setDark: (value: boolean) => void; search: string; setSearch: (value: string) => void; mobileNav: boolean; setMobileNav: (value: boolean) => void; onSignOut: () => void; onAuth: (mode?: "signin" | "signup") => void; onDoctor: (doctor: typeof doctors[number]) => void; onDemoRole: (role: UserRole) => void }) {
  const current = navItems.find(item => item.id === view) ?? navItems[0];
  return <div className="page-glow min-h-screen"><div className="mx-auto flex min-h-screen max-w-[1600px] gap-5 p-4 lg:p-6"><aside className={(mobileNav ? "fixed inset-y-4 left-4 z-50 flex w-[280px] " : "hidden lg:flex lg:w-[260px] ") + "glass-deep flex-col rounded-3xl p-4 text-primary-foreground"}><div className="flex items-center justify-between"><Logo /><button className="grid size-9 place-items-center rounded-xl text-muted-foreground lg:hidden" onClick={() => setMobileNav(false)} aria-label="Close navigation"><X /></button></div><div className="mt-7 rounded-2xl border border-foreground/10 bg-foreground/5 p-3"><div className="flex items-center gap-2"><div className="grid size-9 place-items-center rounded-xl bg-primary text-primary-foreground"><UserRound className="size-4" /></div><div className="min-w-0"><p className="truncate text-sm font-semibold text-foreground">{session.name}</p><p className="text-[10px] capitalize text-muted-foreground">{session.role.replaceAll("_", " ")}</p></div></div></div><nav className="mt-5 flex-1 space-y-1 overflow-auto">{navItems.map(item => { const Icon = item.icon; return <button key={item.id} onClick={() => selectView(item.id)} className={item.id === view ? "flex w-full items-center gap-3 rounded-xl bg-primary px-3 py-2.5 text-left text-sm font-medium text-primary-foreground" : "flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-left text-sm text-muted-foreground transition hover:bg-foreground/5 hover:text-foreground"}><Icon className="size-4" />{item.label}{item.id === "notifications" && <span className="ml-auto grid size-5 place-items-center rounded-full bg-danger text-[10px] text-destructive-foreground">3</span>}</button>; })}</nav><div className="border-t border-foreground/10 pt-3"><button onClick={() => setDark(!dark)} className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-muted-foreground hover:bg-foreground/5 hover:text-foreground">{dark ? <Sun className="size-4" /> : <Moon className="size-4" />}{dark ? "Light mode" : "Dark mode"}</button><button onClick={onSignOut} className="flex w-full items-center gap-3 rounded-xl px-3 py-2.5 text-sm text-muted-foreground hover:bg-foreground/5 hover:text-foreground"><LogOut className="size-4" />Sign out</button></div></aside>{mobileNav && <button className="fixed inset-0 z-40 bg-ink/50 lg:hidden" onClick={() => setMobileNav(false)} aria-label="Close menu overlay" />}
  <main className="min-w-0 flex-1"><header className="glass-panel flex items-center gap-3 rounded-2xl px-3 py-3 sm:px-5"><button className="grid size-10 place-items-center rounded-xl text-muted-foreground hover:bg-foreground/5 lg:hidden" onClick={() => setMobileNav(true)} aria-label="Open navigation"><Menu /></button><div className="min-w-0 flex-1"><p className="text-xs uppercase tracking-[0.18em] text-muted-foreground">MediConnect workspace</p><h1 className="truncate font-display text-xl font-bold text-foreground">{current.label}</h1></div><div className="hidden items-center gap-2 rounded-xl border border-border bg-background/40 px-3 sm:flex"><Search className="size-4 text-muted-foreground" /><Input value={search} onChange={e => setSearch(e.target.value)} className="h-8 w-36 border-0 bg-transparent p-0 text-xs shadow-none focus-visible:ring-0" placeholder="Search care…" /></div><button className="relative grid size-10 place-items-center rounded-xl text-muted-foreground hover:bg-foreground/5" onClick={() => selectView("notifications")} aria-label="Notifications"><Bell className="size-4" /><span className="absolute right-2 top-2 size-1.5 rounded-full bg-danger" /></button><button className="grid size-10 place-items-center rounded-xl bg-primary/10 text-primary" onClick={() => selectView("profile")} aria-label="Open profile"><UserRound className="size-4" /></button></header><div className="mt-5">{view === "overview" && <Dashboard onNavigate={selectView} onDoctor={onDoctor} />}{view === "assistant" && <AssistantPage onNavigate={selectView} />}{view === "doctors" && <DoctorsPage onDoctor={onDoctor} search={search} />}{view === "appointments" && <AppointmentsPage onNavigate={selectView} />}{view === "hospitals" && <HospitalsPage />}{view === "labs" && <LabsPage />}{view === "reports" && <ReportsPage />}{view === "medicine" && <MedicinePage />}{view === "history" && <HistoryPage />}{view === "notifications" && <NotificationsPage />}{view === "profile" && <ProfilePage session={session} onDemoRole={onDemoRole} />}</div></main></div></div>;
}

function PageHeading({ eyebrow, title, copy, action }: { eyebrow: string; title: string; copy: string; action?: React.ReactNode }) { return <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[0.18em] text-primary">{eyebrow}</p><h2 className="mt-2 font-display text-3xl font-bold tracking-tight text-foreground sm:text-4xl">{title}</h2><p className="mt-2 max-w-2xl text-sm leading-relaxed text-muted-foreground">{copy}</p></div>{action}</div>; }
function Card({ children, className = "" }: { children: React.ReactNode; className?: string }) { return <section className={`glass-panel rounded-3xl p-5 ${className}`}>{children}</section>; }
function Dashboard({ onNavigate, onDoctor }: { onNavigate: (view: View) => void; onDoctor: (doctor: typeof doctors[number]) => void }) { return <div className="space-y-5"><PageHeading eyebrow="Patient dashboard · Demo data" title="Good morning, Amara" copy="Your care network is synced. You have one appointment today and two reports ready for review." action={<Button variant="destructive" onClick={() => toast.error("Call your local emergency services for immediate help.")}><AlertTriangle /> Emergency help</Button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[["Next appointment","Dr. Aisha Verma","Today · 3:30 PM","primary",CalendarDays,"appointments"],["Lab report ready","Complete Blood Count","MedLab · 2 hours ago","brand",FileText,"reports"],["Care network","3 hospitals nearby","Last synced 2 min ago","primary",Hospital,"hospitals"],["Prescription","2 items to fill","Wellcare Pharmacy","warning",Pill,"medicine"]].map(([label,value,meta,tone,Icon,target]) => <button key={label as string} onClick={() => onNavigate(target as View)} className="glass-panel rounded-2xl p-4 text-left transition hover:-translate-y-1"><div className="flex items-start justify-between"><span className="text-[10px] font-medium uppercase tracking-[0.15em] text-muted-foreground">{label as string}</span><Icon className="size-4 text-primary" /></div><p className="mt-3 text-base font-semibold text-foreground">{value as string}</p><p className="mt-1 text-xs text-muted-foreground">{meta as string}</p></button>)}</div><div className="grid gap-5 xl:grid-cols-12"><div className="space-y-5 xl:col-span-8"><Card><div className="flex items-center justify-between"><div><p className="font-display text-lg font-semibold">Quick care actions</p><p className="text-xs text-muted-foreground">Move from question to care in a few taps.</p></div><Activity className="size-5 text-primary" /></div><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4">{[["Talk to AI","Get general guidance",MessageCircle,"assistant"],["Book doctor","Video or in-person",Stethoscope,"doctors"],["Find a lab","Home collection",FlaskConical,"labs"],["Find medicine","Compare nearby",Pill,"medicine"]].map(([t,s,Icon,target]) => <button key={t as string} onClick={() => onNavigate(target as View)} className="rounded-2xl border border-border bg-background/30 p-4 text-left transition hover:border-primary/40 hover:bg-primary/5"><Icon className="size-5 text-primary" /><p className="mt-5 text-sm font-semibold text-foreground">{t as string}</p><p className="mt-1 text-xs text-muted-foreground">{s as string}</p></button>)}</div></Card><Card><div className="flex items-center justify-between"><div><p className="font-display text-lg font-semibold">Recent activity</p><p className="text-xs text-muted-foreground">Your connected health records</p></div><Button variant="ghost" size="sm" onClick={() => onNavigate("history")}>View timeline <ArrowRight /></Button></div><div className="mt-5 space-y-4">{[["Report ready","Complete Blood Count","Today, 11:20 AM",FileText,"primary"],["Appointment confirmed","Dr. Aisha Verma · Cardiology","Today, 3:30 PM",CalendarDays,"brand"],["Prescription uploaded","2 medicines · Verification pending","Yesterday, 4:48 PM",Pill,"warning"]].map(([title,meta,time,Icon]) => <div key={title as string} className="flex items-center gap-3"><div className="grid size-10 shrink-0 place-items-center rounded-xl bg-primary/10 text-primary"><Icon className="size-4" /></div><div className="min-w-0 flex-1"><p className="text-sm font-medium text-foreground">{title as string}</p><p className="truncate text-xs text-muted-foreground">{meta as string}</p></div><p className="hidden text-[11px] text-muted-foreground sm:block">{time as string}</p></div>)}</div></Card></div><div className="space-y-5 xl:col-span-4"><HospitalAvailability /><Upcoming onDoctor={onDoctor} /><Card><div className="flex items-center gap-3"><div className="grid size-10 place-items-center rounded-xl bg-primary/10 text-primary"><ShieldCheck className="size-5" /></div><div><p className="text-sm font-semibold">Your records stay private</p><p className="text-xs text-muted-foreground">Only authorized care teams can view shared reports.</p></div></div></Card></div></div></div>; }

function HospitalAvailability({ className = "", onOpen }: { className?: string; onOpen?: () => void }) { return <Card className={className}><div className="flex items-start justify-between"><div><p className="font-display text-lg font-semibold">Hospital availability</p><p className="mt-1 text-xs text-muted-foreground">City Care Hospital · Updated 2 min ago</p></div><Badge className="border-0 bg-primary/10 text-primary">Live demo</Badge></div><div className="mt-5 space-y-4">{[["General beds","42 / 250 free",17,"primary"],["ICU beds","7 / 30 free",23,"warning"],["Emergency beds","5 / 25 free",20,"danger"]].map(([label,value,width,tone]) => <div key={label as string}><div className="flex justify-between text-xs"><span className="text-muted-foreground">{label as string}</span><span className="font-medium text-foreground">{value as string}</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-foreground/10"><div className={(tone === "warning" ? "bg-warning" : tone === "danger" ? "bg-danger" : "bg-primary") + " h-full rounded-full"} style={{ width: `${width}%` }} /></div></div>)}</div><div className="mt-5 grid grid-cols-3 gap-2">{[["18","Doctors"],["46","Nurses"],["4","Ambulances"]].map(([n,l]) => <div key={l} className="rounded-2xl bg-background/35 p-3"><p className="font-display text-xl font-bold text-foreground">{n}</p><p className="text-[10px] text-muted-foreground">{l}</p></div>)}</div><Button variant="outline" className="mt-5 w-full" onClick={onOpen}>View hospital network <ArrowRight /></Button></Card>; }
function BedChart({ className = "" }: { className?: string }) { return <Card className={className}><div className="flex items-start justify-between"><div><p className="font-display text-lg font-semibold">Bed occupancy</p><p className="mt-1 text-xs text-muted-foreground">7-day trend · % used</p></div><Badge variant="secondary">Trending</Badge></div><div className="mt-6 flex h-44 items-end justify-between gap-2">{[[52,"Mon"],[64,"Tue"],[78,"Wed"],[60,"Thu"],[71,"Fri"],[88,"Sat"],[94,"Sun"]].map(([height,day], i) => <div key={day as string} className="flex h-full flex-1 flex-col items-center gap-2"><div className={(i === 2 || i > 4 ? "bg-warning" : "bg-primary") + " bar-grow w-full rounded-lg opacity-80"} style={{ height: `${height}%`, animationDelay: `${i * 80}ms` }} /><span className="text-[10px] text-muted-foreground">{day}</span></div>)}</div></Card>; }
function Upcoming({ onDoctor }: { onDoctor?: (doctor: typeof doctors[number]) => void }) { return <Card><div className="flex items-center justify-between"><div><p className="font-display text-lg font-semibold">Upcoming</p><p className="mt-1 text-xs text-muted-foreground">Your next visits</p></div><CalendarDays className="size-5 text-primary" /></div><button className="mt-5 flex w-full items-center gap-3 rounded-2xl bg-background/40 p-3 text-left transition hover:bg-primary/5" onClick={() => onDoctor?.(doctors[0])}><img src={doctorAisha} alt="Dr. Aisha Verma" loading="lazy" width={768} height={768} className="size-11 rounded-xl object-cover" /><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold text-foreground">Dr. Aisha Verma</p><p className="text-xs text-muted-foreground">Cardiology · Today 3:30 PM</p></div><Badge className="border-0 bg-primary/10 text-primary">Confirmed</Badge></button><button className="mt-3 flex w-full items-center gap-3 rounded-2xl border border-border p-3 text-left transition hover:bg-primary/5"><img src={doctorMenon} alt="Dr. Rohan Mehta" loading="lazy" width={768} height={768} className="size-9 rounded-lg object-cover" /><div className="flex-1"><p className="text-xs font-semibold text-foreground">Dr. Rohan Mehta</p><p className="text-[11px] text-muted-foreground">Neurology · Wed 11:00 AM</p></div><Video className="size-4 text-muted-foreground" /></button></Card>; }

function AssistantPage({ onNavigate }: { onNavigate: (view: View) => void }) { const [messages, setMessages] = useState([{ role: "assistant", text: "I’m here to help with general health information. Tell me what you’re feeling, how long it has lasted, and how severe it feels." }, { role: "user", text: "I have a fever and mild headache." }, { role: "assistant", text: "Rest and fluids may help with a common viral illness. If your temperature reaches 39.4°C, symptoms persist beyond 3 days, or you develop chest pain or difficulty breathing, please seek medical care." }]); const [input, setInput] = useState(""); const send = () => { if (!input.trim()) return; setMessages(prev => [...prev, { role: "user", text: input }, { role: "assistant", text: "Thanks for sharing. How old are you, when did this start, and do you have any existing conditions or medication allergies? I can offer general information, not a diagnosis." }]); setInput(""); }; return <div className="space-y-5"><PageHeading eyebrow="Private patient workspace" title="AI Health Assistant" copy="A calm starting point for questions, with safety cues built into every response." action={<Badge className="border-0 bg-primary/10 px-3 py-1.5 text-primary"><LockKeyhole className="mr-1 size-3" /> Secure chat</Badge>} /><div className="grid gap-5 xl:grid-cols-12"><Card className="flex min-h-[620px] flex-col p-0 xl:col-span-8"><div className="flex items-center gap-3 border-b border-border px-5 py-4"><div className="grid size-10 place-items-center rounded-xl bg-gradient-to-br from-brand to-cyan-400 text-primary-foreground">✦</div><div><p className="text-sm font-semibold text-foreground">MediConnect AI</p><p className="text-xs text-primary">General information · not a diagnosis</p></div></div><ScrollArea className="flex-1 p-5"><div className="space-y-5">{messages.map((message, index) => <div key={`${message.text}-${index}`} className={message.role === "user" ? "flex justify-end" : "flex gap-3"}>{message.role === "assistant" && <div className="grid size-8 shrink-0 place-items-center rounded-full bg-primary/10 text-primary">✦</div>}<div className={message.role === "user" ? "max-w-[80%] rounded-2xl rounded-tr-md bg-primary px-4 py-3 text-sm text-primary-foreground" : "max-w-[84%] rounded-2xl rounded-tl-md bg-background/50 px-4 py-3 text-sm leading-relaxed text-foreground ring-1 ring-border"}>{message.text}</div></div>)}</div></ScrollArea><div className="border-t border-border p-4"><div className="flex gap-2"><Textarea value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => { if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); send(); } }} className="min-h-12 resize-none bg-background/40" placeholder="Describe your symptoms…" /><Button onClick={send} size="icon" aria-label="Send message"><Send /></Button></div><div className="mt-3 flex flex-wrap gap-2"><Button variant="outline" size="sm" onClick={() => onNavigate("doctors")}>Book a doctor</Button><Button variant="outline" size="sm" onClick={() => onNavigate("hospitals")}>Find nearby hospital</Button><Button variant="destructive" size="sm" onClick={() => toast.error("Possible medical emergency: contact local emergency services now.")}>Emergency help</Button></div></div></Card><div className="space-y-5 xl:col-span-4"><Card className="border-danger/25 bg-danger/5"><div className="flex gap-3"><AlertTriangle className="mt-0.5 size-5 text-danger" /><div><p className="text-sm font-semibold text-danger">Safety first</p><p className="mt-1 text-xs leading-relaxed text-muted-foreground">Chest pain, difficulty breathing, severe bleeding, loss of consciousness, stroke-like symptoms, or severe allergic reaction need immediate emergency care.</p></div></div></Card><Card><p className="font-display text-lg font-semibold">How I’ll help</p><div className="mt-4 space-y-3">{[["Understand","Ask about age, duration, severity and context.",MessageCircle],["Guide","Share common possibilities and self-care ideas.",HeartPulse],["Escalate","Point out warning signs and when to see a clinician.",ShieldCheck]].map(([title,copy,Icon]) => <div key={title as string} className="flex gap-3"><div className="grid size-9 place-items-center rounded-xl bg-primary/10 text-primary"><Icon className="size-4" /></div><div><p className="text-sm font-medium text-foreground">{title as string}</p><p className="mt-0.5 text-xs leading-relaxed text-muted-foreground">{copy as string}</p></div></div>)}</div></Card></div></div></div>; }

function DoctorsPage({ onDoctor, search }: { onDoctor: (doctor: typeof doctors[number]) => void; search: string }) { const filtered = doctors.filter(d => `${d.name} ${d.specialty} ${d.hospital}`.toLowerCase().includes(search.toLowerCase())); return <div className="space-y-5"><PageHeading eyebrow="Connected specialists" title="Find a doctor" copy="Search by specialty, experience, hospital or availability. Demo profiles are clearly labelled." action={<Button onClick={() => toast.success("Location access is ready for your next search.")} variant="outline"><LocateFixed /> Near me</Button>} /><div className="grid gap-4 md:grid-cols-2">{filtered.map((doctor) => <Card key={doctor.name} className="transition hover:-translate-y-1"><div className="flex gap-4"><img src={doctor.image} alt={doctor.name} loading="lazy" width={768} height={768} className="size-20 rounded-2xl object-cover" /><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><div><p className="text-base font-semibold text-foreground">{doctor.name}</p><p className="mt-1 text-xs text-primary">{doctor.specialty}</p></div><Badge className="border-0 bg-primary/10 text-primary">★ {doctor.rating}</Badge></div><p className="mt-3 text-xs text-muted-foreground">{doctor.hospital} · {doctor.exp}</p><p className="mt-1 text-xs text-muted-foreground">{doctor.availability}</p><div className="mt-4 flex items-center justify-between"><span className="text-sm font-semibold text-foreground">{doctor.fee}<span className="ml-1 text-xs font-normal text-muted-foreground">/ consultation</span></span><Button size="sm" onClick={() => onDoctor(doctor)}>Book appointment <ArrowRight /></Button></div></div></div></Card>)}{filtered.length === 0 && <Card className="md:col-span-2"><div className="py-14 text-center"><Search className="mx-auto size-8 text-muted-foreground" /><p className="mt-3 font-display text-xl font-semibold">No doctors found</p><p className="mt-1 text-sm text-muted-foreground">Try a specialty, name or hospital.</p></div></Card>}</div></div>; }

function AppointmentsPage({ onNavigate }: { onNavigate: (view: View) => void }) { const [booking, setBooking] = useState(false); return <div className="space-y-5"><PageHeading eyebrow="Your care schedule" title="Appointments" copy="Keep upcoming, completed and cancelled visits together in one place." action={<Button onClick={() => setBooking(true)}><CalendarDays /> Book appointment</Button>} /><div className="grid gap-5 xl:grid-cols-3"><Card className="xl:col-span-2"><Tabs defaultValue="upcoming"><TabsList><TabsTrigger value="upcoming">Upcoming <Badge className="ml-2 border-0 bg-primary/10 text-primary">3</Badge></TabsTrigger><TabsTrigger value="completed">Completed</TabsTrigger><TabsTrigger value="cancelled">Cancelled</TabsTrigger></TabsList><TabsContent value="upcoming" className="mt-5 space-y-3">{[["Dr. Aisha Verma","Cardiology","Today · 3:30 PM","Video","Confirmed"],["Dr. Rohan Mehta","Neurology","Wed · 11:00 AM","In-person","Upcoming"],["MedLab Diagnostics","Complete Blood Count","Fri · 8:30 AM","Lab test","Booked"]].map(([name,specialty,time,type,status]) => <div key={name as string} className="flex flex-wrap items-center gap-3 rounded-2xl border border-border bg-background/30 p-4"><div className="grid size-10 place-items-center rounded-xl bg-primary/10 text-primary">{type === "Video" ? <Video className="size-4" /> : type === "Lab test" ? <TestTube2 className="size-4" /> : <Stethoscope className="size-4" />}</div><div className="min-w-[160px] flex-1"><p className="text-sm font-semibold text-foreground">{name as string}</p><p className="text-xs text-muted-foreground">{specialty as string} · {type as string}</p></div><p className="text-xs text-muted-foreground">{time as string}</p><Badge className="border-0 bg-primary/10 text-primary">{status as string}</Badge><Button size="sm" variant="ghost" onClick={() => toast.success("Appointment details copied")}>Details <ChevronRight /></Button></div>)}</TabsContent><TabsContent value="completed" className="mt-5"><EmptyState title="No completed appointments yet" copy="Completed visits will appear here." /></TabsContent><TabsContent value="cancelled" className="mt-5"><EmptyState title="No cancelled appointments" copy="Your cancelled visits will appear here." /></TabsContent></Tabs></Card><Card><p className="font-display text-lg font-semibold">Appointment guide</p><div className="mt-5 space-y-4">{[["Choose","Select a trusted specialist.",1],["Schedule","Pick a time that works.",2],["Connect","Join securely or visit in person.",3]].map(([t,c,n]) => <div key={t as string} className="flex gap-3"><span className="grid size-7 shrink-0 place-items-center rounded-full bg-primary text-xs font-semibold text-primary-foreground">{n}</span><div><p className="text-sm font-semibold text-foreground">{t as string}</p><p className="text-xs text-muted-foreground">{c as string}</p></div></div>)}</div><Button variant="outline" className="mt-6 w-full" onClick={() => onNavigate("doctors")}>Browse doctors <ArrowRight /></Button></Card></div>{booking && <BookingDialog open={booking} onOpenChange={setBooking} doctor={doctors[0]} />}</div>; }

function BookingDialog({ open, onOpenChange, doctor }: { open: boolean; onOpenChange: (open: boolean) => void; doctor: typeof doctors[number] }) { const [step, setStep] = useState(1); return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent><DialogHeader><DialogTitle>Book with {doctor.name}</DialogTitle><DialogDescription>Demo booking flow · no payment required</DialogDescription></DialogHeader><div className="mt-2 flex items-center gap-2">{["Doctor","Time","Confirm"].map((label, index) => <div key={label} className="flex flex-1 items-center gap-2"><span className={step >= index + 1 ? "grid size-7 place-items-center rounded-full bg-primary text-xs text-primary-foreground" : "grid size-7 place-items-center rounded-full bg-muted text-xs text-muted-foreground"}>{step > index + 1 ? <Check className="size-3" /> : index + 1}</span><span className="text-xs text-muted-foreground">{label}</span>{index < 2 && <div className="h-px flex-1 bg-border" />}</div>)}</div>{step === 1 && <div className="mt-5 rounded-2xl bg-background/40 p-4"><div className="flex items-center gap-3"><img src={doctor.image} alt={doctor.name} width={768} height={768} className="size-14 rounded-xl object-cover" /><div><p className="font-semibold text-foreground">{doctor.name}</p><p className="text-xs text-muted-foreground">{doctor.specialty} · {doctor.hospital}</p></div></div><Button className="mt-5 w-full" onClick={() => setStep(2)}>Choose date and time <ArrowRight /></Button></div>}{step === 2 && <div className="mt-5 space-y-3"><div className="grid grid-cols-2 gap-3"><Button variant="outline" onClick={() => setStep(3)}>Today · 3:30 PM</Button><Button variant="outline" onClick={() => setStep(3)}>Today · 4:20 PM</Button><Button variant="outline" onClick={() => setStep(3)}>Tomorrow · 10:00 AM</Button><Button variant="outline" onClick={() => setStep(3)}>Wed · 11:00 AM</Button></div><Button variant="ghost" onClick={() => setStep(1)}>Back</Button></div>}{step === 3 && <div className="mt-5 space-y-4"><div className="rounded-2xl border border-primary/30 bg-primary/5 p-4"><p className="text-sm font-semibold text-foreground">Your appointment is ready to confirm</p><p className="mt-1 text-xs text-muted-foreground">Video consultation · Today at 3:30 PM · Fee {doctor.fee}</p></div><Button className="w-full" onClick={() => { onOpenChange(false); setStep(1); toast.success("Appointment confirmed — reminder added"); }}>Confirm appointment <Check /></Button><Button variant="ghost" onClick={() => setStep(2)}>Back</Button></div>}</DialogContent></Dialog>; }

function HospitalsPage() { return <div className="space-y-5"><PageHeading eyebrow="Connected hospital network · Demo data" title="Hospital availability" copy="Compare beds, ICU capacity, emergency resources and care teams. This sample data is not real-time hospital information." action={<Button variant="outline" onClick={() => toast.success("Location access is ready for your next search.")}><MapPin /> Near me</Button>} /><div className="grid gap-5 xl:grid-cols-12"><Card className="min-h-[360px] overflow-hidden xl:col-span-5"><div className="flex items-center justify-between"><p className="font-display text-lg font-semibold">Nearby care map</p><Badge variant="secondary">Demo map</Badge></div><div className="relative mt-5 grid min-h-[270px] place-items-center overflow-hidden rounded-2xl border border-border bg-gradient-to-br from-primary/10 via-background to-accent/20"><div className="absolute inset-0 opacity-35 [background-image:linear-gradient(var(--color-border)_1px,transparent_1px),linear-gradient(90deg,var(--color-border)_1px,transparent_1px)] [background-size:34px_34px]" /><div className="relative flex flex-col items-center gap-3"><div className="grid size-14 place-items-center rounded-full bg-primary/15 text-primary ring-8 ring-primary/10"><LocateFixed /></div><p className="text-sm font-medium text-foreground">Bengaluru care network</p><p className="text-xs text-muted-foreground">Map integration ready for production key</p></div>{[["18%","30%"],["65%","23%"],["44%","68%"]].map(([x,y], i) => <span key={i} className="absolute grid size-8 place-items-center rounded-full bg-primary text-primary-foreground shadow-lg" style={{ left: x, top: y }}><Hospital className="size-3" /></span>)}</div></Card><div className="space-y-3 xl:col-span-7">{hospitals.map(hospital => <Card key={hospital.name} className="p-4"><div className="flex flex-wrap items-start gap-3"><div className="grid size-10 place-items-center rounded-xl bg-primary/10 text-primary"><Hospital className="size-5" /></div><div className="min-w-[180px] flex-1"><div className="flex items-center gap-2"><p className="text-sm font-semibold text-foreground">{hospital.name}</p><Badge className={hospital.status === "Limited" ? "border-0 bg-warning/15 text-warning" : "border-0 bg-primary/10 text-primary"}>{hospital.status}</Badge></div><p className="mt-1 text-xs text-muted-foreground">{hospital.location} · Emergency department open</p></div><Button size="sm" variant="outline" onClick={() => toast.success(`${hospital.name} visit request started`)}>Request visit</Button></div><div className="mt-4 grid grid-cols-3 gap-2 sm:grid-cols-6">{[["Beds",hospital.beds],["ICU",hospital.icu],["Emergency",hospital.emergency],["Doctors",hospital.doctors],["Nurses",hospital.nurses],["Ambulances",hospital.name === "City Care Hospital" ? 4 : 2]].map(([label,value]) => <div key={label as string} className="rounded-xl bg-background/40 p-2.5"><p className="text-[10px] text-muted-foreground">{label as string}</p><p className="mt-1 text-xs font-semibold text-foreground">{value as string}</p></div>)}</div></Card>)}</div></div></div>; }

function LabsPage() { return <div className="space-y-5"><PageHeading eyebrow="Diagnostics network" title="Find a lab" copy="Book a test, request home collection, and keep the report in your private record." action={<Button onClick={() => toast.success("Home collection preferences saved")}><TestTube2 /> Book a test</Button>} /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{labs.map(lab => <Card key={lab.name} className="transition hover:-translate-y-1"><div className="flex items-start justify-between"><div className="grid size-11 place-items-center rounded-2xl bg-primary/10 text-primary"><FlaskConical /></div><Badge className="border-0 bg-primary/10 text-primary">★ {lab.rating}</Badge></div><p className="mt-5 font-display text-lg font-semibold text-foreground">{lab.name}</p><p className="mt-1 text-xs text-muted-foreground">{lab.location} · {lab.distance}</p><p className="mt-4 text-xs text-foreground">{lab.tests}</p><div className="mt-4 flex items-center justify-between"><span className={lab.home ? "text-xs font-medium text-primary" : "text-xs text-muted-foreground"}>{lab.home ? "Home collection" : "Visit lab only"}</span><Button size="sm" onClick={() => toast.success(`${lab.name} selected for test booking`)}>View tests</Button></div></Card>)}</div><Card><div className="flex flex-wrap items-center gap-3"><div className="grid size-10 place-items-center rounded-xl bg-primary/10 text-primary"><Clock3 /></div><div className="flex-1"><p className="text-sm font-semibold text-foreground">Popular tests</p><p className="text-xs text-muted-foreground">CBC · Blood Sugar · Lipid Profile · Thyroid · Vitamin D · ECG</p></div><Button variant="outline">Browse all tests <ArrowRight /></Button></div></Card></div>; }

function ReportsPage() { return <div className="space-y-5"><PageHeading eyebrow="Private records" title="My lab reports" copy="Track every stage from booking to doctor review. Reports are visible only to authorized users." action={<Button variant="outline"><FileText /> Download all</Button>} /><Card><div className="space-y-3">{reports.map(report => <div key={report.test} className="flex flex-wrap items-center gap-3 rounded-2xl border border-border bg-background/30 p-4"><div className="grid size-10 place-items-center rounded-xl bg-primary/10 text-primary"><FileText className="size-4" /></div><div className="min-w-[180px] flex-1"><p className="text-sm font-semibold text-foreground">{report.test}</p><p className="text-xs text-muted-foreground">{report.lab} · Booked {report.date}</p></div><div className="hidden items-center gap-1 sm:flex">{["Booked","Collected","Processing","Ready"].map((stage, i) => <div key={stage} className="flex items-center gap-1"><span className={i <= (report.tone === "ready" ? 3 : report.tone === "reviewed" ? 3 : 2) ? "size-2 rounded-full bg-primary" : "size-2 rounded-full bg-muted"} />{i < 3 && <span className="h-px w-4 bg-border" />}</div>)}</div><Badge className={report.tone === "processing" ? "border-0 bg-warning/15 text-warning" : "border-0 bg-primary/10 text-primary"}>{report.status}</Badge><Button size="sm" variant="ghost" onClick={() => toast.success(report.tone === "processing" ? "Report is still processing" : "Secure report viewer opened")}>{report.tone === "processing" ? "Track" : "View"} <ChevronRight /></Button></div>)}</div></Card></div>; }

function MedicinePage() { const [uploaded, setUploaded] = useState(false); return <div className="space-y-5"><PageHeading eyebrow="Pharmacy network" title="Find medicine" copy="Compare nearby availability and prices. Prescription medicines require pharmacist verification." action={<Button variant="outline" onClick={() => setUploaded(true)}><Syringe /> Upload prescription</Button>} /><div className="grid gap-5 xl:grid-cols-12"><Card className="xl:col-span-7"><div className="flex items-center gap-3"><div className="grid size-11 place-items-center rounded-2xl bg-primary/10 text-primary"><Search /></div><div><p className="font-display text-lg font-semibold">Search 50+ medicines</p><p className="text-xs text-muted-foreground">Try a generic or brand name</p></div></div><div className="mt-5 flex gap-2"><Input placeholder="Search medicine name…" /><Button onClick={() => toast.success("Showing nearby pharmacy prices")}><Search /></Button></div>{uploaded && <div className="mt-4 rounded-2xl border border-primary/25 bg-primary/5 p-4"><div className="flex gap-3"><Check className="size-5 text-primary" /><div><p className="text-sm font-semibold text-foreground">Possible medicines detected</p><p className="mt-1 text-xs text-muted-foreground">Amoxicillin 500 mg · Paracetamol 500 mg</p><p className="mt-2 text-[11px] text-warning">Please verify the medicine name and prescription with a qualified pharmacist or doctor.</p></div></div></div>}<div className="mt-5 space-y-3">{[["Paracetamol 500 mg","Generic · Tablet","₹24 – ₹38","In stock"],["Amoxicillin 500 mg","Prescription · Capsule","₹96 – ₹124","Verification needed"],["Cetirizine 10 mg","Generic · Tablet","₹18 – ₹29","In stock"]].map(([name,meta,price,status]) => <div key={name as string} className="flex flex-wrap items-center gap-3 rounded-2xl border border-border p-4"><div className="grid size-9 place-items-center rounded-xl bg-primary/10 text-primary"><Pill className="size-4" /></div><div className="flex-1"><p className="text-sm font-semibold text-foreground">{name as string}</p><p className="text-xs text-muted-foreground">{meta as string}</p></div><p className="text-sm font-semibold text-foreground">{price as string}</p><Badge className={status === "In stock" ? "border-0 bg-primary/10 text-primary" : "border-0 bg-warning/15 text-warning"}>{status as string}</Badge></div>)}</div></Card><Card className="xl:col-span-5"><div className="flex items-center gap-3"><div className="grid size-11 place-items-center rounded-2xl bg-primary/10 text-primary"><LocateFixed /></div><div><p className="font-display text-lg font-semibold">Nearby pharmacies</p><p className="text-xs text-muted-foreground">Compare prices and stock</p></div></div><div className="mt-5 space-y-3">{["Wellcare Pharmacy · 350 m","24Seven Meds · 900 m","Apollo Health Store · 1.8 km"].map((store, i) => <div key={store} className="flex items-center gap-3 rounded-2xl bg-background/35 p-3"><div className="grid size-9 place-items-center rounded-xl bg-primary/10 text-primary"><Pill className="size-4" /></div><div className="flex-1"><p className="text-sm font-medium text-foreground">{store.split(" · ")[0]}</p><p className="text-xs text-muted-foreground">{store.split(" · ")[1]} · {i === 2 ? "Open until 11 PM" : "Open now"}</p></div><Button size="sm" variant="outline" onClick={() => toast.success("Pharmacy details opened")}>View</Button></div>)}</div></Card></div></div>; }

function HistoryPage() { return <div className="space-y-5"><PageHeading eyebrow="Your care story" title="Medical history" copy="A private timeline of appointments, reports and prescriptions you choose to keep together." action={<Button variant="outline"><FileText /> Export records</Button>} /><Card><div className="relative ml-3 border-l border-border pl-7">{[["Today","CBC report ready","MedLab Diagnostics","Report ready",FileText],["Today","Cardiology appointment","Dr. Aisha Verma","Confirmed",CalendarDays],["Yesterday","Prescription added","2 medicines","Verification pending",Pill],["12 Jun 2025","Thyroid profile","HealthCheck Labs","Doctor reviewed",Activity]].map(([date,title,meta,status,Icon]) => <div key={`${date}-${title}`} className="relative pb-8 last:pb-1"><span className="absolute -left-[35px] grid size-4 place-items-center rounded-full border-4 border-background bg-primary" /><div className="flex flex-wrap items-start gap-3"><div className="grid size-9 place-items-center rounded-xl bg-primary/10 text-primary"><Icon className="size-4" /></div><div className="flex-1"><p className="text-[11px] font-medium uppercase tracking-[0.15em] text-muted-foreground">{date as string}</p><p className="mt-1 text-sm font-semibold text-foreground">{title as string}</p><p className="mt-1 text-xs text-muted-foreground">{meta as string}</p></div><Badge className="border-0 bg-primary/10 text-primary">{status as string}</Badge></div></div>)}</div></Card></div>; }
function NotificationsPage() { return <div className="space-y-5"><PageHeading eyebrow="Care updates" title="Notifications" copy="Appointment confirmations, report updates and pharmacy requests appear here." action={<Button variant="outline" onClick={() => toast.success("All notifications marked as read")}><Check /> Mark all read</Button>} /><Card><div className="space-y-2">{[["Appointment confirmed","Dr. Aisha Verma · Today at 3:30 PM","5 min ago",CalendarDays],["Lab report ready","Complete Blood Count is ready to view","2 hours ago",FileText],["Prescription verification","Wellcare Pharmacy requested a valid prescription","Yesterday",Pill]].map(([title,meta,time,Icon]) => <button key={title as string} onClick={() => toast.success("Notification opened")} className="flex w-full items-center gap-3 rounded-2xl p-3 text-left transition hover:bg-primary/5"><div className="grid size-10 place-items-center rounded-xl bg-primary/10 text-primary"><Icon className="size-4" /></div><div className="min-w-0 flex-1"><p className="text-sm font-semibold text-foreground">{title as string}</p><p className="truncate text-xs text-muted-foreground">{meta as string}</p></div><p className="text-[11px] text-muted-foreground">{time as string}</p><ChevronRight className="size-4 text-muted-foreground" /></button>)}</div></Card></div>; }
function ProfilePage({ session, onDemoRole }: { session: SessionUser; onDemoRole: (role: UserRole) => void }) { return <div className="space-y-5"><PageHeading eyebrow="Account & permissions" title="Your profile" copy="Keep your details current and choose a demo workspace to preview role-aware permissions." action={<Button onClick={() => toast.success("Profile changes saved securely")}><Check /> Save changes</Button>} /><div className="grid gap-5 xl:grid-cols-12"><Card className="xl:col-span-7"><div className="flex items-center gap-4"><div className="grid size-16 place-items-center rounded-2xl bg-primary text-2xl font-bold text-primary-foreground">{session.name.split(" ").map(part => part[0]).join("").slice(0,2)}</div><div><p className="font-display text-xl font-semibold text-foreground">{session.name}</p><p className="text-sm text-muted-foreground">{session.email}</p><Badge className="mt-2 border-0 bg-primary/10 text-primary">{session.role.replaceAll("_", " ")}</Badge></div></div><div className="mt-7 grid gap-4 sm:grid-cols-2"><label className="text-xs font-medium text-muted-foreground">Full name<Input className="mt-2" defaultValue={session.name} /></label><label className="text-xs font-medium text-muted-foreground">City<Input className="mt-2" defaultValue="Bengaluru" /></label><label className="text-xs font-medium text-muted-foreground">Blood group<Input className="mt-2" defaultValue="O+" /></label><label className="text-xs font-medium text-muted-foreground">Emergency contact<Input className="mt-2" defaultValue="+91 98765 43210" /></label></div></Card><Card className="xl:col-span-5"><p className="font-display text-lg font-semibold">Preview workspaces</p><p className="mt-1 text-xs text-muted-foreground">Switch safely between role dashboards for your demo.</p><div className="mt-5 grid grid-cols-2 gap-2">{([["patient","Patient"],["doctor","Doctor"],["laboratory_staff","Lab staff"],["medical_store","Pharmacy"],["hospital_admin","Hospital admin"],["nurse","Nurse"]] as [UserRole,string][]).map(([value,label]) => <Button key={value} variant={session.role === value ? "default" : "outline"} size="sm" onClick={() => onDemoRole(value)}>{label}</Button>)}</div><div className="mt-5 rounded-2xl border border-primary/20 bg-primary/5 p-4"><div className="flex gap-3"><ShieldCheck className="size-5 text-primary" /><p className="text-xs leading-relaxed text-muted-foreground">Role changes in this preview are demo-only. Production permissions are enforced by the secure backend.</p></div></div></Card></div></div>; }
function EmptyState({ title, copy }: { title: string; copy: string }) { return <div className="py-12 text-center"><div className="mx-auto grid size-12 place-items-center rounded-2xl bg-primary/10 text-primary"><FileText className="size-5" /></div><p className="mt-3 font-display text-lg font-semibold text-foreground">{title}</p><p className="mt-1 text-sm text-muted-foreground">{copy}</p></div>; }

function AuthDialog({ open, onOpenChange, mode, setMode }: { open: boolean; onOpenChange: (open: boolean) => void; mode: "signin" | "signup"; setMode: (mode: "signin" | "signup") => void }) { const [email, setEmail] = useState(""); const [password, setPassword] = useState(""); const [name, setName] = useState(""); const [busy, setBusy] = useState(false); const submit = async () => { setBusy(true); const result = mode === "signin" ? await supabase.auth.signInWithPassword({ email, password }) : await supabase.auth.signUp({ email, password, options: { data: { full_name: name, user_type: "patient" } } }); setBusy(false); if (result.error) { toast.error(result.error.message); return; } toast.success(mode === "signin" ? "Welcome back to MediConnect" : "Check your email to verify your account"); onOpenChange(false); }; const google = async () => { setBusy(true); const result = await lovable.auth.signInWithOAuth("google", { redirect_uri: window.location.origin }); setBusy(false); if (result.error) toast.error(result.error.message); }; return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent><DialogHeader><DialogTitle>{mode === "signin" ? "Welcome back" : "Create your care account"}</DialogTitle><DialogDescription>Secure access to appointments, reports and your care network.</DialogDescription></DialogHeader><div className="mt-3 space-y-3">{mode === "signup" && <Input value={name} onChange={e => setName(e.target.value)} placeholder="Full name" /> }<Input value={email} onChange={e => setEmail(e.target.value)} placeholder="Email address" type="email" /><Input value={password} onChange={e => setPassword(e.target.value)} placeholder="Password" type="password" /><Button className="w-full" onClick={submit} disabled={busy}>{busy ? "Please wait…" : mode === "signin" ? "Sign in" : "Create account"}</Button><Button variant="outline" className="w-full" onClick={google} disabled={busy}>Continue with Google</Button><p className="text-center text-xs text-muted-foreground">{mode === "signin" ? "New to MediConnect?" : "Already have an account?"} <button className="font-medium text-primary underline-offset-4 hover:underline" onClick={() => setMode(mode === "signin" ? "signup" : "signin")}>{mode === "signin" ? "Create account" : "Sign in"}</button></p><p className="text-center text-[11px] leading-relaxed text-muted-foreground">By continuing, you agree to the healthcare support disclaimer. AI guidance is general information only.</p></div></DialogContent></Dialog>; }
